3. Open `/modules/paypal/views/templates/front/order-confirmation.tpl` and add at the bottom:

```
<script type="text/javascript">
  _kkstrack = {
    {literal}merchantInfo: [{ country:"COUNTRY", merchantId:"COM_ID" }],{/literal}
    orderValue: '{$sales}',
    orderId: '{$orderid}',
    basket: {$products_json}
  };
  (function() {
    var s = document.createElement('script');
    s.type = 'text/javascript';
    s.async = true;
    s.src = 'https://s.kk-resources.com/ks.js';
    var x = document.getElementsByTagName('script')[0];
    x.parentNode.insertBefore(s, x);
  })();
</script>
```

Note this PayPal snippet uses the placeholder `COM_ID` for the merchant ID, where the main conversion tag uses `MERCHANTID_VALUE`.

